#define FG_CONV_L20_NO_MAIN
#include "rtx_oracle.cpp"
#include "custom_conv2_contract.h"
namespace{namespace c=fg_custom_conv2;
void Receipt(const std::filesystem::path&p,const c::Layer&l,const std::string&id,std::uint8_t poison,const std::vector<std::uint8_t>&w0,const std::vector<std::uint8_t>&b0,const std::vector<std::uint8_t>&a0,const std::vector<std::uint8_t>&r0,const std::vector<std::uint8_t>&w1,const std::vector<std::uint8_t>&b1,const std::vector<std::uint8_t>&a1,const std::vector<std::uint8_t>&r1,const std::vector<std::uint8_t>&out,std::size_t mismatch,std::size_t canary,std::size_t collisions){std::ofstream s(p);bool pass=mismatch==0&&canary==0;s<<"{\n  \"schema\": \"neuralstudio.fg.custom-conv2-run.v1\",\n  \"backend\": \"rtx-cuda-driver\",\n  \"layer_id\": \""<<l.id<<"\",\n  \"run_id\": \""<<id<<"\",\n  \"process_id\": "<<GetCurrentProcessId()<<",\n  \"poison_byte\": "<<unsigned(poison)<<",\n  \"trace_launch_token\": \"launch-"<<std::setw(6)<<std::setfill('0')<<l.launch<<"\",\n"<<std::setfill(' ')<<"  \"module_token\": 57,\n  \"module_bytes\": "<<c::kModuleBytes<<",\n  \"module_sha256\": \""<<c::kModuleSha256<<"\",\n  \"function_name\": \"custom_block0_conv2_kernel\",\n  \"grid\": [10, 23, 1],\n  \"block\": [32, 1, 8],\n  \"packed_parameter_bytes\": 92,\n  \"abi_scalars\": [64, 3, 3, 64, 1, 46, 80, 64, 1, 46, 80, 64, "<<(l.residual?1:0)<<"],\n  \"input_shape_nhwc\": [1, 46, 80, 64],\n  \"output_shape_nhwc\": [1, 46, 80, 64],\n  \"fused_operations\": [\"conv3x3\", \"leaky_relu\", \"clamp_-6_6\", \"optional_residual_add\"],\n  \"residual_enabled\": "<<(l.residual?"true":"false")<<",\n  \"weight_source_token\": "<<l.weight_token<<",\n  \"bias_source_token\": "<<l.bias_token<<",\n  \"model_capture_manifest_sha256\": \""<<c::kManifestSha256<<"\",\n  \"weight_pre_sha256\": \""<<Sha256(w0)<<"\",\n  \"weight_post_sha256\": \""<<Sha256(w1)<<"\",\n  \"bias_pre_sha256\": \""<<Sha256(b0)<<"\",\n  \"bias_post_sha256\": \""<<Sha256(b1)<<"\",\n  \"input_generator\": \"splitmix64-fg-custom-conv2-v1\",\n  \"input_pre_sha256\": \""<<Sha256(a0)<<"\",\n  \"input_post_sha256\": \""<<Sha256(a1)<<"\",\n  \"residual_pre_sha256\": \""<<Sha256(r0)<<"\",\n  \"residual_post_sha256\": \""<<Sha256(r1)<<"\",\n  \"output_sha256\": \""<<Sha256(out)<<"\",\n  \"output_bytes\": "<<out.size()<<",\n  \"input_mismatched_bytes\": "<<mismatch<<",\n  \"canary_mismatched_bytes\": "<<canary<<",\n  \"per_run_poison_collision_halfwords\": "<<collisions<<",\n  \"per_run_write_coverage_conclusive\": false,\n  \"external_model_files_opened\": true,\n  \"expected_output_file_opened\": false,\n  \"address_fields_recorded\": false,\n  \"result\": \""<<(pass?"pass":"fail")<<"\"\n}\n";}}
int main(int argc,char**argv){if(argc!=8){std::cerr<<"usage=fg-custom-conv2-rtx <layer> <module> <weights> <bias> <out> <run> <poison>\n";return 2;}try{const auto&l=c::Find(argv[1]);auto module=Read(argv[2]),w0=Read(argv[3]),b0=Read(argv[4]);if(module.size()!=c::kModuleBytes||Sha256(module)!=c::kModuleSha256||w0.size()!=c::kWeightBytes||Sha256(w0)!=l.weight_sha256||b0.size()!=c::kBiasBytes||Sha256(b0)!=l.bias_sha256)throw std::runtime_error("identity mismatch");char*e=nullptr;auto pv=std::strtoul(argv[7],&e,16);if(e==argv[7]||*e!='\0'||pv>255)throw std::runtime_error("poison");auto poison=std::uint8_t(pv);std::filesystem::path outdir=argv[5];std::filesystem::create_directories(outdir);auto a0=c::Input(l,false),r0=c::Input(l,true);Check(cuInit(0),"init");CUdevice d=0;Check(cuDeviceGet(&d,0),"device");CUcontext ctx=nullptr;Check(cuDevicePrimaryCtxRetain(&ctx,d),"retain");Check(cuCtxSetCurrent(ctx),"ctx");CUmodule m=nullptr;Check(cuModuleLoadData(&m,module.data()),"module");CUfunction f=nullptr;Check(cuModuleGetFunction(&f,m,"custom_block0_conv2_kernel"),"function");GuardedDeviceBuffer w,b,a,r,o;w.Allocate(c::kWeightBytes);b.Allocate(c::kBiasBytes);a.Allocate(c::kTensorBytes);r.Allocate(c::kTensorBytes);o.Allocate(c::kTensorBytes);Check(cuMemcpyHtoD(w.payload(),w0.data(),w0.size()),"w");Check(cuMemcpyHtoD(b.payload(),b0.data(),b0.size()),"b");Check(cuMemcpyHtoD(a.payload(),a0.data(),a0.size()),"a");Check(cuMemcpyHtoD(r.payload(),r0.data(),r0.size()),"r");Check(cuMemsetD8(o.payload(),poison,c::kTensorBytes),"o");CUdeviceptr wp=w.payload(),bp=b.payload(),ap=a.payload(),rp=r.payload(),op=o.payload();std::uint32_t oc=64,kh=3,kw=3,ic=64,batch=1,h=46,width=80,stride=64,flag=l.residual?1u:0u;void*params[]={&wp,&bp,&oc,&kh,&kw,&ic,&ap,&rp,&batch,&h,&width,&stride,&op,&batch,&h,&width,&stride,&flag};Check(cuLaunchKernel(f,10,23,1,32,1,8,0,nullptr,params,nullptr),"launch");Check(cuCtxSynchronize(),"sync");auto wg=w.ReadAll(),bg=b.ReadAll(),ag=a.ReadAll(),rg=r.ReadAll(),og=o.ReadAll();auto w1=Payload(wg,c::kWeightBytes),b1=Payload(bg,c::kBiasBytes),a1=Payload(ag,c::kTensorBytes),r1=Payload(rg,c::kTensorBytes),out=Payload(og,c::kTensorBytes);auto mismatch=Mismatches(w0,w1)+Mismatches(b0,b1)+Mismatches(a0,a1)+Mismatches(r0,r1);auto canary=CanaryMismatches(wg,c::kWeightBytes)+CanaryMismatches(bg,c::kBiasBytes)+CanaryMismatches(ag,c::kTensorBytes)+CanaryMismatches(rg,c::kTensorBytes)+CanaryMismatches(og,c::kTensorBytes);Receipt(outdir/"run-receipt.json",l,argv[6],poison,w0,b0,a0,r0,w1,b1,a1,r1,out,mismatch,canary,UntouchedHalfwords(out,poison));Write(outdir/"output.bin",out);Write(outdir/"input-after.bin",a1);bool pass=mismatch==0&&canary==0;std::cout<<"probe=fg_custom_conv2_rtx\nlayer="<<l.id<<"\noutput_sha256="<<Sha256(out)<<"\nresult="<<(pass?"pass":"fail")<<'\n';w.Free();b.Free();a.Free();r.Free();o.Free();Check(cuModuleUnload(m),"unload");Check(cuDevicePrimaryCtxRelease(d),"release");return pass?0:3;}catch(const std::exception&x){std::cerr<<"error="<<x.what()<<'\n';return 1;}}
